sib['award_id'],\n                'org_id': sib['org_id'],\n                'status_code': sib['status_code'],\n                'remaining_balance': float(sib['remaining_balance']),\n                'discovered_via_active_award': act['award_id'],\n                'failure_kinds': sorted({f['failure_kind'] for f in failures}),\n            })\n\nworld.close()",
